```javascript
function divisors(num) {
    let ret = [];
    let i;
    for (i = 2; i * i < num; i++) {
        if (num % i === 0) {
            ret.push(i);
            ret.push(Math.floor(num / i));
        }
    }
    if (i * i === num) {
        ret.push(i);
    }
    return ret;
}

function main() {
    const input = require('fs').readFileSync('input.in', 'utf8').trim().split(/\s+/).map(Number);
    let idx = 0;
    let output = [];
    while (idx < input.length) {
        const n = input[idx++];
        const m = input[idx++];
        const k = input[idx++];
        if (n % 2 === 0) {
            output.push("Marsel");
            continue;
        }
        let div = divisors(m);
        let flag = false;
        if (m > 1) {
            div.push(1);
        }
        for (let i = 0; i < div.length && !flag; i++) {
            if (div[i] >= k) {
                flag = true;
            }
        }
        output.push(flag ? "Timur" : "Marsel");
    }
    require('fs').writeFileSync('output.out', output.join('\n'));
}

main();
