function main() {
    const readline = require('readline');
    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout
    });

    rl.on('line', (line) => {
        const [n, m, k] = line.split(' ').map(Number);
        if (n % 2 === 0) {
            console.log("Marsel");
            return;
        }
        let div = divisors(m);
        let flag = false;
        if (m > 1) {
            div.push(1);
        }
        for (let i = 0; i < div.length && !flag; i++) {
            if (div[i] >= k) {
                flag = true;
            }
        }
        console.log(flag ? "Timur" : "Marsel");
    });

    rl.on('close', () => {
        process.exit(0);
    });
}

main();

